package com.bananalab.lite;
import org.json.*;
public final class Stage54NaturalCheck{
 static void check(boolean ok,String why){if(!ok)throw new AssertionError(why);}
 static void plan(String input,String kind,String command)throws Exception{NaturalCoding.Plan p=NaturalCoding.parse(input,"");check(p.kind.equals(kind),input+" -> "+p.kind+" wanted "+kind);if(command!=null)check(p.command.equals(command),input+" -> "+p.command);}
 public static void main(String[] args)throws Exception{
  for(String q:new String[]{"cambia el color de los botones a azul","podes cambiar los botones de la app a azules","quiero que cambies los botones a azul","pone los botones azules","Banana, por favor podes cambiar los botones a azul","quiero que los botones sean azules"})plan(q,"settings","pone los botones de la app azul");
  for(String q:new String[]{"agranda la letra","hace el texto del chat mas grande","quiero que agrandes el texto del chat","necesito que la letra del chat sea mas grande"})plan(q,"settings","agranda el texto del chat");
  plan("cambia el fondo de la app a violeta","settings","pone el tema de la app violeta");plan("crea una pantalla de proyectos","settings","crea una pantalla de proyectos");plan("agranda la letra y cambia los botones a verde","settings","agranda el texto del chat;pone los botones de la app verde");
  for(String q:new String[]{"crea una funcion que sume los positivos de una lista","haceme un metodo para sumar los positivos de una lista","suma los positivos de una lista","quiero que el chat sume los positivos de una lista"})plan(q,"method","suma los positivos de una lista");
  plan("que cambiaste","status",null);plan("como va el cambio","status",null);
  plan("invierte texto en minusculas","method","invierte texto en minusculas");plan("crea una funcion que alterna turnos desde el ultimo personaje","method","alterna turnos desde el ultimo personaje");
  plan("cuando te diga \"buenas banana\" respondas \"Buenas, ¿qué creamos?\"","reply",null);plan("quiero que cuando diga \"saludo local\" responda \"Buenas\"","reply",null);
  plan("probalo con: -3,2,5","test","-3,2,5");plan("probalo con -3,2,5","test","-3,2,5");plan("incorporalo a la app","build","reconstruye mi apk");plan("genera una apk normal","build","reconstruye mi apk");plan("arregla que el segundo personaje no aparece","diagnose",null);plan("cambia los botones a azul y borra mis escenas","diagnose",null);
  for(String q:new String[]{"hola","que es java","como cambio el color de los botones","no cambies los botones a azul","crea a Fito un zorro; agrega una banana llamada Bani","pone a Tony azul","hace que la banana baile","alterna dialogo 4 turnos","genera metodo java: suma los positivos de una lista","cambia el metodo del chat: cuando diga \"hola\" responde \"buenas\""})plan(q,"",null);
  check(NaturalCoding.parse("y mas grande","text").command.equals("agranda el texto del chat"),"follow-up text");check(NaturalCoding.parse("y mas grande","buttons").command.equals("agranda los botones de la app"),"follow-up buttons");check(NaturalCoding.parse("y mas grande","").kind.equals("clarify"),"no invented context");
  try{NaturalCoding.parse("crea una funcion que sume los positivos de una lista excepto cinco","");throw new AssertionError("partial method");}catch(IllegalArgumentException expected){}
  AppJavaWorkspace.Settings base=new AppJavaWorkspace.Settings();JSONObject legacy=base.json();legacy.remove("accent");check(AppJavaWorkspace.Settings.read(legacy).accent==0,"legacy settings compatible");check(!AppJavaWorkspace.sources(base).get("BananaInterface.java").contains("buttonAccent"),"legacy canonical source preserved");AppJavaChat.Plan colored=AppJavaChat.plan("pone los botones de la app verde",base);check(colored.settings.accent==2&&base.accent==0,"isolated color plan");check(AppJavaWorkspace.sources(colored.settings).get("BananaInterface.java").contains("buttonAccent() { return 2; }"),"real compiled color getter");ChatEdits.validate(new JSONObject().put("settings",colored.settings.json()).put("replies",JSONObject.NULL));try{ChatEdits.validate(new JSONObject().put("settings",colored.settings.json().put("accent",99)).put("replies",JSONObject.NULL));throw new AssertionError("invalid baked settings");}catch(IllegalArgumentException expected){}
  System.out.println("PASS Stage54 natural routing, complete requests, negation, scene separation, follow-ups, canonical colors and legacy settings");
 }
}
